function AccountPasswordControl({target,csrf}){const [open,setOpen]=useState(false),[password,setPassword]=useState(''),[show,setShow]=useState(false),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);const save=async()=>{if(password.length<12){setMessage('Use at least 12 characters.');return}setBusy(true);try{const r=await fetch(API+'/api/admin/users/'+target.id+'/password',{method:'PATCH',credentials:'include',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({password})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not reset password.');setPassword('');setMessage('Password reset. Share it securely with the account holder.')}catch(e){setMessage(e.message)}finally{setBusy(false)}};return <div className="password-reset"><button type="button" className="account-reset-toggle" onClick={()=>setOpen(!open)}>{open?'Close password reset':'Reset login password'}</button>{open&&<div className="password-reset-form"><span>{target.role==='STUDENT'?'Student signs in at /portal':target.role==='TEACHER'?'Teacher signs in at /teacher':'Use the account’s role portal'}</span><label>New password<span className="password-control"><input type={show?'text':'password'} minLength="12" value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 12 characters"/><button type="button" onClick={()=>setShow(!show)}>{show?'Hide':'Show'}</button></span></label><button type="button" className="button button-green" disabled={busy||password.length<12} onClick={save}>{busy?'Saving…':'Set new password'}</button>{message&&<small role="status">{message}</small>}</div>}</div>}
