 const createAccount=async e=>{e.preventDefault();setBusy(true);setMsg('');try{const r=await fetch(`${API}/api/admin/users`,{method:'POST',credentials:'include',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(accountForm)});const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not create the account.');if(accountPhoto&&d.user?.id){const body=new FormData();body.append('image',accountPhoto);const photo=await fetch(`${API}/api/admin/users/${d.user.id}/photo`,{method:'POST',credentials:'include',headers:{'X-CSRF-Token':csrf},body});const pd=await photo.json();if(!photo.ok)throw new Error(`Account created, but profile photo upload failed: ${pd.error||'check R2 settings'}`)}const refreshed=await fetch(`${API}/api/admin/users`,{credentials:'include'});const list=await refreshed.json().catch(()=>({}));setUsers(list.users||[d.user,...users]);setAccountForm({name:'',email:'',password:'',role:'STUDENT',schoolDivision:'',admissionNumber:'',staffNumber:'',classGroupId:'',gender:'',guardianName:'',guardianPhone:'',guardianEmail:''});setAccountPhoto(null);setMsg(`Account created. ${d.user?.role==='STUDENT'?'Student signs in at /portal using admission number or email.':d.user?.role==='TEACHER'?'Teacher signs in at /teacher.':'Share the correct portal URL and temporary password securely.'}`)}catch(e){setMsg(e.message)}finally{setBusy(false)}};
